// js
// quantity: the months HR counted under art.46(2), service less unemployment-insured time and time already paid.
const wage = ctx.month_wage;
const full_years = Math.trunc(ctx.entry.quantity / 12);
const remainder = ctx.entry.quantity % 12;
const half_month = wage * ctx.lookup.half_month_share;
if (remainder > ctx.lookup.half_year_remainder_months) return half_month * (full_years + 1);
if (remainder > 0) return half_month * (full_years + ctx.lookup.half_year_share);
return half_month * full_years;

